from pathlib import Path
from PIL import Image
import json,hashlib,shutil,html
R=Path(__file__).parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2),encoding='utf-8')
sources=json.loads((R/'sources.json').read_text(encoding='utf-8'))['games']
plan=json.loads((R/'generation-plan.json').read_text(encoding='utf-8'))
assets=[]
manual=json.loads((R/'manual-measurements.json').read_text(encoding='utf-8')) if (R/'manual-measurements.json').exists() else {}
for s in sources:
 p=R/s['id']/'character.png'
 if not p.exists():continue
 im=Image.open(p);a=im.getchannel('A') if 'A'in im.getbands() else None
 b=a.point(lambda v:255 if v>=32 else 0).getbbox() if a else (0,0,*im.size)
 m=manual.get(s['id'],{})
 top=m.get('hairTop',b[1]);sole=m.get('sole',b[3]-1);foot=m.get('footX',(b[0]+b[2])/2)
 assets.append({'id':s['id'],'label':s['game'],'file':p.relative_to(R).as_posix(),'sha256':sha(p),'width':im.width,'height':im.height,'mode':im.mode,'hasAlpha':a is not None,'alphaExtrema':a.getextrema() if a else None,'boundsAlpha32':b,'boundsAlpha1':a.point(lambda v:255 if v>=1 else 0).getbbox() if a else b,'bodyHeight':sole-top+1,'hairTop':top,'sole':sole,'footX':foot,'footY':sole,'measurementMethod':'alpha>=32 support plus manual hair/sole/body review; blades excluded from body height; coordinates native pixels','measurementEstimated':True,'uncertaintyPixels':m.get('uncertaintyPixels',5),'headObservation':m.get('headObservation','visual proportion inspection pending'),'sourceGame':s['game'],'sourceReference':s['reference'],'generationInput':s['id']+'/generation-input.json','rawGeneratedBytesUnmodified':True})
for a in assets:
 if a['id'] in ['03_priconne','09_dfo'] and (R/a['id']/'rework-result-01.json').exists():a['generationInput']=a['id']+'/rework-input-01.json'
write(R/'asset-manifest.json',{'task':'MAIN01-20261109-E1FD458C','iteration':2,'assets':assets,'displayRule':'CSS uniform body height / sole baseline; original PNG bytes never resampled/reencoded','technicalScope':'rendering/proportion exploration, not native sprite delivery or game integration'})
orig=[]
for model,file in [('a','sd-pose-original.png'),('b','combat-ready-illustration-proportions.png')]:
 src=R.parent/'combat_ready_right045_illustration_proportions_v02'/file;dst=R/('source-model-'+model+'.png')
 if not dst.exists():shutil.copyfile(src,dst)
 orig.append({'model':model,'file':dst.name,'source':str(src),'sha256':sha(dst),'byteIdentical':sha(src)==sha(dst)})
write(R/'original-inputs.json',orig)
data=[dict(a,analysis=next(s for s in sources if s['id']==a['id'])) for a in assets]
